package com.funfriday.service;
import com.funfriday.db.dao.PlayerLogicGridProgressDao;import com.funfriday.games.logicgrid.*;import com.funfriday.model.*;import lombok.RequiredArgsConstructor;import lombok.extern.slf4j.Slf4j;import org.springframework.stereotype.Service;
@Slf4j @Service @RequiredArgsConstructor public class PlayerLogicGridProgressService {private final PlayerLogicGridProgressDao dao;public void recordCurrentProgress(GameRoom room,String player){if(!(room.getGameData() instanceof LogicGridData d)||player==null)return;if(!(d.getScoreBoard().get(player) instanceof LogicGridPlayerStats s))return;try{dao.save(player,d.getPuzzleId(),(int)Math.round(s.getProgress()),s.getStatus()==PlayerStatus.COMPLETED);}catch(Exception e){log.warn("Unable to save Logic Grid progress",e);}}}
